import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

sigmoid_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void sigmoid_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        output[idx] = 1.0f / (1.0f + expf(-val));
    }
}

torch::Tensor custom_sigmoid_cuda(torch::Tensor input) {
    auto size = input.numel();
    auto output = torch::zeros_like(input);

    const int block_size = 256;
    const int grid_size = (size + block_size - 1) / block_size;

    sigmoid_kernel<<<grid_size, block_size>>>(input.data_ptr<float>(),
                                              output.data_ptr<float>(),
                                              size);
    return output;
}
"""

sigmoid_cpp_header = """
torch::Tensor custom_sigmoid_cuda(torch::Tensor input);
"""

# Compile the inline CUDA code for custom sigmoid
custom_sigmoid = load_inline(
    name="custom_sigmoid",
    cpp_sources=sigmoid_cpp_header,
    cuda_sources=sigmoid_cuda_src,
    functions=["custom_sigmoid_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Simple model that performs a custom Sigmoid activation via a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies custom sigmoid to the input tensor.
        """
        return custom_sigmoid.custom_sigmoid_cuda(x)

